package vendor

import spinal.core._

/** GTS Direct PHY variant from agilex5/gts/gen_ip.sh (`variant`: sfp1): duplex, single width, parallel data
  * first bit in bit 0. */
case class GtsDuplex(variant: String, lockToRef: Boolean = false) extends BlackBox {
  setDefinitionName(variant)
  val i_rx_cdr_refclk_p, i_tx_pll_refclk_p, i_pma_cu_clk = in Bool ()
  val i_tx_reset, i_rx_reset = in Bool ()
  val o_tx_reset_ack, o_rx_reset_ack, o_tx_ready, o_rx_ready = out Bool ()
  val i_tx_coreclkin, i_rx_coreclkin = in Bool ()
  val o_tx_clkout, o_rx_clkout = out Bool ()
  val i_src_rs_grant = in Bool ()
  val o_src_rs_req = out Bool ()
  val o_tx_serial_data, o_tx_serial_data_n = out Bool ()
  val i_rx_serial_data, i_rx_serial_data_n = in Bool ()
  val o_tx_pll_locked, o_rx_is_lockedtodata, o_rx_is_lockedtoref = out Bool ()
  val i_rx_set_locktoref = lockToRef generate in(Bool())
  val i_tx_parallel_data = in Bits (80 bits)
  val o_rx_parallel_data = out Bits (80 bits)
  noIoPrefix()
}

/** Shared reference clock and reset sequencer of the GTS lanes (one req/grant pair per lane). */
case class GtsSrcss(lanes: Int) extends BlackBox {
  setDefinitionName("srcss")
  val o_src_rs_grant = out Bits (lanes bits)
  val i_src_rs_priority, i_src_rs_req = in Bits (lanes bits)
  val o_pma_cu_clk = out Bool ()
  val i_src_rs_refclk_status_bus = in Bits (10 bits)
  val o_refclk_fail_status = out Bits (8 bits)
  val o_refclk_on_ack = out Bool ()
  val i_refclk_on = in Bits (10 bits)
  val o_src_rs_refclk_cmd_bus = out Bits (10 bits)
  noIoPrefix()
}

/** Clock network divider from gen_ip.sh (pon_clocks): inclk and inclk / 2, aligned and timed as related clocks. */
case class PonClocks() extends BlackBox {
  setDefinitionName("pon_clocks")
  val inclk = in Bool ()
  val clock_div1x, clock_div2x = out Bool ()
  noIoPrefix()
}

/** I/O PLL from gen_ip.sh (helper_pll), from a 50 MHz board oscillator: the VCXO loops' helper clocks, 155.357 MHz
  * (GPON, halved 311.04 MHz clocks) and 62.143 MHz (EPON, halved 125 MHz clocks). */
case class HelperPll() extends BlackBox {
  setDefinitionName("helper_pll")
  val refclk, rst = in Bool ()
  val outclk_0, outclk_1, locked = out Bool ()
  noIoPrefix()
}

/** SFP cage 0 (channel 0), the ONU BOSA lane (channel 1) and its burst enable lane (channel 2, TX only), each
  * with a GPON and a 1.25 Gb/s DR profile (dr_top, generated by quartus_tlg from the gen_ip.sh variants, see fit.sh):
  * per channel its shared ports, per profile the ports of a GtsDuplex. one_hot_sel (dr_top's mux order, by instance name):
  * bit 0 ben_1g25, 1 ben_tx, 2 onu_1g25, 3 onu, 4 sfp0_1g25, 5 sfp0. */
case class GtsDrLanes() extends BlackBox {
  setDefinitionName("dr_top")
  val i_pma_cu_clk_bank0 = in Bool ()
  val one_hot_sel = in Bits (6 bits)
  case class Channel(k: Int, rx: Boolean = true) {
    def port[T <: Data](name: String, data: T): T = data.setName(s"${name}_ch$k")
    val i_dr_lavmm_addr = port("i_dr_lavmm_addr", in Bits (21 bits))
    val i_dr_lavmm_be = port("i_dr_lavmm_be", in Bits (4 bits))
    val i_dr_lavmm_clk = port("i_dr_lavmm_clk", in Bool ())
    val i_dr_lavmm_read = port("i_dr_lavmm_read", in Bool ())
    val i_dr_lavmm_rstn = port("i_dr_lavmm_rstn", in Bool ())
    val i_dr_lavmm_write = port("i_dr_lavmm_write", in Bool ())
    val i_dr_lavmm_wdata = port("i_dr_lavmm_wdata", in Bits (32 bits))
    val o_dr_lavmm_rdata = port("o_dr_lavmm_rdata", out Bits (32 bits))
    val o_dr_lavmm_rdata_valid = port("o_dr_lavmm_rdata_valid", out Bool ())
    val o_dr_lavmm_waitreq = port("o_dr_lavmm_waitreq", out Bool ())
    val i_rs_grant = port("i_rs_grant", in Bool ())
    val o_rs_request = port("o_rs_request", out Bool ())
    val i_src_pause_request = port("i_src_pause_request", in Bool ())
    val o_src_pause_grant = port("o_src_pause_grant", out Bool ())
    val i_rx_serial_data_p = rx generate port("i_rx_serial_data_p", in Bool ())
    val i_rx_serial_data_n = rx generate port("i_rx_serial_data_n", in Bool ())
    val o_tx_serial_data_p = port("o_tx_serial_data_p", out Bool ())
    val o_tx_serial_data_n = port("o_tx_serial_data_n", out Bool ())
  }
  case class Profile(suffix: String, lockToRef: Boolean = false, rx: Boolean = true) {
    def port[T <: Data](name: String, data: T): T = data.setName(s"${name}_$suffix")
    def rxPort[T <: Data](name: String, data: => T): T = rx generate port(name, data)
    val i_tx_pll_refclk_p = port("i_tx_pll_refclk_p", in Bool ())
    val i_tx_coreclkin = port("i_tx_coreclkin", in Bool ())
    val o_tx_clkout = port("o_tx_clkout", out Bool ())
    val i_tx_reset = port("i_tx_reset", in Bool ())
    val o_tx_reset_ack = port("o_tx_reset_ack", out Bool ())
    val o_tx_ready = port("o_tx_ready", out Bool ())
    val o_tx_pll_locked = port("o_tx_pll_locked", out Bool ())
    val i_tx_parallel_data = port("i_tx_parallel_data", in Bits (80 bits))
    val i_rx_cdr_refclk_p = rxPort("i_rx_cdr_refclk_p", in Bool ())
    val i_rx_coreclkin = rxPort("i_rx_coreclkin", in Bool ())
    val o_rx_clkout = rxPort("o_rx_clkout", out Bool ())
    val i_rx_reset = rxPort("i_rx_reset", in Bool ())
    val i_rx_set_locktoref = (rx && lockToRef) generate port("i_rx_set_locktoref", in Bool ())
    val o_rx_reset_ack = rxPort("o_rx_reset_ack", out Bool ())
    val o_rx_ready = rxPort("o_rx_ready", out Bool ())
    val o_rx_is_lockedtodata = rxPort("o_rx_is_lockedtodata", out Bool ())
    val o_rx_is_lockedtoref = rxPort("o_rx_is_lockedtoref", out Bool ())
    val o_rx_parallel_data = rxPort("o_rx_parallel_data", out Bits (80 bits))
  }
  val sfp0 = Channel(0)
  val onu = Channel(1)
  val ben = Channel(2)
  val sfp0Gpon = Profile("sfp0_inst", lockToRef = true)
  val sfp0Epon = Profile("sfp0_1g25_inst", lockToRef = true)
  val onuGpon = Profile("onu_inst")
  val onuEpon = Profile("onu_1g25_inst")
  val benGpon = Profile("ben_tx_inst", lockToRef = true) // its receiver: the upstream sniffer (bursts)
  val benEpon = Profile("ben_1g25_inst", lockToRef = true)
  noIoPrefix()
}

/** GTS dynamic reconfiguration controller from gen_ip.sh (dr_ctrl), the PON lanes: host CSRs (byte addresses
  * 0-0x7C) on the management clock, each channel's local AVMM and the profile select towards dr_top. */
case class GtsDrCtrl() extends BlackBox {
  setDefinitionName("dr_ctrl")
  val i_rst_n, i_csr_clk, i_cpu_clk = in Bool ()
  val o_profile_id = out Bits (15 bits)
  val o_in_progress, o_err_status, o_fast_sim_clk_sel = out Bool ()
  val i_host_avmm_address = in UInt (7 bits)
  val i_host_avmm_read, i_host_avmm_write = in Bool ()
  val i_host_avmm_writedata = in Bits (32 bits)
  val o_host_avmm_readdata = out Bits (32 bits)
  val o_host_avmm_readdatavalid, o_host_avmm_waitrequest = out Bool ()
  val o_one_hot_sel = out Bits (6 bits)
  val o_src_pause_request = out Bits (3 bits)
  val i_src_pause_grant = in Bits (3 bits)
  case class Lavmm(k: Int) {
    def port[T <: Data](name: String, data: T): T = data.setName(s"${name.head}_ch${k}_lavmm_${name.tail}")
    val addr = port("oaddr", out Bits (21 bits))
    val be = port("obe", out Bits (4 bits))
    val write = port("owrite", out Bool ())
    val read = port("oread", out Bool ())
    val rstn = port("orstn", out Bool ())
    val wdata = port("owdata", out Bits (32 bits))
    val rdata = port("irdata", in Bits (32 bits))
    val rdataValid = port("irdata_valid", in Bool ())
    val waitreq = port("iwaitreq", in Bool ())

    /** To the DR lanes' channel. */
    def drive(channel: GtsDrLanes#Channel, clk: Bool): Unit = {
      channel.i_dr_lavmm_clk := clk
      channel.i_dr_lavmm_addr := addr
      channel.i_dr_lavmm_be := be
      channel.i_dr_lavmm_read := read
      channel.i_dr_lavmm_write := write
      channel.i_dr_lavmm_wdata := wdata
      channel.i_dr_lavmm_rstn := rstn
      rdata := channel.o_dr_lavmm_rdata
      rdataValid := channel.o_dr_lavmm_rdata_valid
      waitreq := channel.o_dr_lavmm_waitreq
    }
  }
  val ch0 = Lavmm(0)
  val ch1 = Lavmm(1)
  val ch2 = Lavmm(2)
  noIoPrefix()
}

/** Clock network mux from gen_ip.sh (clock_mux): a PON side's core clock from its active DR profile, switched only
  * while that side is in reset. */
case class ClockMux() extends BlackBox {
  setDefinitionName("clock_mux")
  val inclk0x, inclk1x = in Bool ()
  val clkselect = in Bool ()
  val outclk = out Bool ()
  noIoPrefix()
}
